import{_ as s,C as e,o as r,c as d,a2 as n,b as l,w as a,a as i,E as u,a3 as g}from"./chunks/framework.CAKCj7G0.js";const D=JSON.parse('{"title":"InfluxDB 概览核心解析","description":"","frontmatter":{},"headers":[],"relativePath":"数据库/InfluxDB/InfluxDB概览.md","filePath":"数据库/InfluxDB/InfluxDB概览.md","lastUpdated":null}'),h={name:"数据库/InfluxDB/InfluxDB概览.md"};function x(p,t,c,B,f,A){const o=e("Mermaid");return r(),d("div",null,[t[1]||(t[1]=n(`<h1 id="influxdb-概览核心解析" tabindex="-1">InfluxDB 概览核心解析 <a class="header-anchor" href="#influxdb-概览核心解析" aria-label="Permalink to &quot;InfluxDB 概览核心解析&quot;">​</a></h1><p>InfluxDB 是业界最广为人知的时序数据库（Time Series Database，TSDB）之一。如果你正在处理按时间顺序产生的大量数据——无论是服务器指标、传感器读数还是金融行情——InfluxDB 几乎一定会出现在你的技术选型清单上。本文将从&quot;什么是时序数据库&quot;讲起，梳理 InfluxDB 的产品定位、版本演进、核心特性、适用场景，以及与同类产品的对比，帮助你在 5 分钟内建立对 InfluxDB 的完整认知。</p><hr><h2 id="什么是时序数据库" tabindex="-1">什么是时序数据库 <a class="header-anchor" href="#什么是时序数据库" aria-label="Permalink to &quot;什么是时序数据库&quot;">​</a></h2><p><strong>时序数据库（Time Series Database，TSDB）</strong> 是一种专门为存储和查询时间序列数据而设计的数据库系统。</p><p><strong>时间序列数据</strong> 指按时间顺序排列的数据点，每个数据点至少包含一个时间戳和一个测量值。典型的例子包括：</p><ul><li>服务器 CPU 使用率每 10 秒采集一次</li><li>智能电表每小时上报一次用电量</li><li>股票交易所每秒推送的行情数据</li><li>应用服务每 5 秒上报一次请求延迟</li></ul><h3 id="与传统关系型数据库的核心差异" tabindex="-1">与传统关系型数据库的核心差异 <a class="header-anchor" href="#与传统关系型数据库的核心差异" aria-label="Permalink to &quot;与传统关系型数据库的核心差异&quot;">​</a></h3><p>传统关系型数据库（如 MySQL、PostgreSQL）的设计目标是支持通用的事务处理（OLTP），强调 ACID 事务、复杂 JOIN 查询和灵活的 Schema 变更。而时序数据库面对的是截然不同的 workload：</p><table tabindex="0"><thead><tr><th>维度</th><th>关系型数据库（如 MySQL）</th><th>时序数据库（如 InfluxDB）</th></tr></thead><tbody><tr><td><strong>写入模式</strong></td><td>随机写入、低频次、需事务保障</td><td>顺序追加写入、高频次、批量写入</td></tr><tr><td><strong>查询模式</strong></td><td>点查、范围扫描、多表 JOIN</td><td>时间范围查询、聚合计算、降采样</td></tr><tr><td><strong>数据特征</strong></td><td>更新频繁、行级修改常见</td><td>几乎不更新、写入后只读或删除</td></tr><tr><td><strong>时间维度</strong></td><td>普通字段之一</td><td>核心排序键、天然分区依据</td></tr><tr><td><strong>Schema</strong></td><td>强 Schema，需预先定义</td><td>弱 Schema 或无 Schema，动态字段</td></tr><tr><td><strong>存储优化</strong></td><td>B+ 树索引、行存为主</td><td>时间分区、列存或专用时序格式、高压缩</td></tr><tr><td><strong>典型 QPS</strong></td><td>数千 TPS</td><td>数十万至数百万 points/秒</td></tr></tbody></table><p>关系型数据库并非不能存储时序数据，但当数据规模达到百万级时间线、每秒百万数据点时，B+ 树索引的维护成本和 JOIN 查询的性能开销会让系统迅速崩溃。时序数据库通过<strong>时间分区</strong>、<strong>列式存储</strong>、<strong>专用压缩算法</strong>和<strong>预聚合机制</strong>，将写入吞吐和查询效率提升一到两个数量级。</p><h3 id="时序数据库的核心设计原则" tabindex="-1">时序数据库的核心设计原则 <a class="header-anchor" href="#时序数据库的核心设计原则" aria-label="Permalink to &quot;时序数据库的核心设计原则&quot;">​</a></h3><p>所有成熟的时序数据库都遵循以下几条设计公理：</p><ol><li><strong>时间即主键</strong>：时间戳不是普通字段，而是数据排序、分区、裁剪的第一依据。</li><li><strong>写入远大于读取</strong>：典型场景下写入 QPS 是查询的 10～100 倍，优化重点在写入路径。</li><li><strong>近期数据优先访问</strong>：80% 的查询集中在最近 24 小时的数据上，冷热分离成为标配。</li><li><strong>聚合先于明细</strong>：监控场景不关心单条原始数据，关心的是&quot;最近 5 分钟的平均值&quot;。</li><li><strong>数据生命周期管理</strong>：时序数据价值随时间衰减，自动过期机制不可或缺。</li></ol><hr><h2 id="influxdb-的产品定位" tabindex="-1">InfluxDB 的产品定位 <a class="header-anchor" href="#influxdb-的产品定位" aria-label="Permalink to &quot;InfluxDB 的产品定位&quot;">​</a></h2><p>InfluxDB 由 <strong>InfluxData</strong> 公司开发，采用 Go 语言编写，于 2013 年首次开源发布。它是 InfluxData 技术栈（简称 <strong>TICK 栈</strong>）的核心组件：</p><table tabindex="0"><thead><tr><th>组件</th><th>角色</th><th>功能</th></tr></thead><tbody><tr><td><strong>Telegraf</strong></td><td>数据采集</td><td>插件式数据收集代理，支持数百种输入源</td></tr><tr><td><strong>InfluxDB</strong></td><td>数据存储</td><td>时序数据的核心存储与查询引擎</td></tr><tr><td><strong>Chronograf</strong></td><td>可视化</td><td>官方仪表盘与数据探索工具</td></tr><tr><td><strong>Kapacitor</strong></td><td>数据处理</td><td>流处理、告警触发、数据转换</td></tr></tbody></table><blockquote><p>注：在 InfluxDB 2.x 中，Chronograf 和 Kapacitor 的功能被合并进内置的 <strong>Tasks</strong> 和 <strong>Alerting</strong> 模块，TICK 栈的概念逐渐弱化，但 Telegraf 仍是独立且活跃的项目。</p></blockquote><p>InfluxDB 的产品定位可以概括为一句话：<strong>&quot;为开发者设计的时序数据平台&quot;</strong>。它的设计哲学强调：</p><ul><li><strong>开箱即用</strong>：单个二进制文件即可运行，无需外部依赖（如 ZooKeeper、HBase）。</li><li><strong>HTTP API 优先</strong>：所有操作都可通过 RESTful API 完成，便于与各种编程语言和工具集成。</li><li><strong>类 SQL 查询</strong>：InfluxQL（1.x）和 Flux（2.x）降低了学习门槛，3.x 回归标准 SQL。</li><li><strong>生态丰富</strong>：与 Grafana、Prometheus、Kafka、Pulsar 等主流工具无缝集成。</li></ul><hr><h2 id="版本演进-1-x-→-2-x-→-3-x" tabindex="-1">版本演进：1.x → 2.x → 3.x <a class="header-anchor" href="#版本演进-1-x-→-2-x-→-3-x" aria-label="Permalink to &quot;版本演进：1.x → 2.x → 3.x&quot;">​</a></h2><p>InfluxDB 的发展历程是理解其当前能力和未来方向的关键。三个大版本代表了存储引擎和查询范式的三次重大变革：</p><h3 id="influxdb-1-x-2013–2020-tsm-引擎奠基" tabindex="-1">InfluxDB 1.x（2013–2020）：TSM 引擎奠基 <a class="header-anchor" href="#influxdb-1-x-2013–2020-tsm-引擎奠基" aria-label="Permalink to &quot;InfluxDB 1.x（2013–2020）：TSM 引擎奠基&quot;">​</a></h3><p>1.x 系列是 InfluxDB 的开源成名作，核心贡献在于 <strong>TSM（Time-Structured Merge Tree）存储引擎</strong>：</p><ul><li><strong>WAL + Cache + TSM File</strong>：写入先进入 WAL（预写日志），再批量写入内存 Cache，最后压缩为只读的 TSM 文件。</li><li><strong>高压缩比</strong>：对时间戳采用 delta-of-delta 编码，对浮点数采用 Gorilla 压缩，典型压缩比可达 10:1。</li><li><strong>Tag 索引（TSI）</strong>：1.3 版本引入 TSI（Time Series Index），解决了高基数标签的内存索引爆炸问题。</li><li><strong>InfluxQL 查询语言</strong>：类 SQL 语法，支持 <code>SELECT</code>、<code>WHERE</code>、<code>GROUP BY</code>、<code>INTO</code> 等标准操作，并扩展了时间窗口聚合函数。</li></ul><p>1.x 的局限也很明显：</p><ul><li><strong>集群闭源</strong>：开源版本仅支持单节点，高可用和集群功能是企业版独占。</li><li><strong>查询能力有限</strong>：InfluxQL 不支持 JOIN 和嵌套子查询，复杂分析需借助 Kapacitor。</li><li><strong>数据类型单一</strong>：早期版本仅支持 float64，后续才扩展至 int、string、bool。</li></ul><h3 id="influxdb-2-x-2020–至今-flux-与统一平台" tabindex="-1">InfluxDB 2.x（2020–至今）：Flux 与统一平台 <a class="header-anchor" href="#influxdb-2-x-2020–至今-flux-与统一平台" aria-label="Permalink to &quot;InfluxDB 2.x（2020–至今）：Flux 与统一平台&quot;">​</a></h3><p>2.x 是 InfluxData 对&quot;平台化&quot;的一次大胆尝试，核心变化包括：</p><ul><li><strong>Bucket 替代 Database + Retention Policy</strong>：将数据库和数据保留策略合并为单一的 <strong>Bucket</strong> 概念，简化数据组织。</li><li><strong>Flux 查询语言</strong>：全新的函数式管道查询语言，支持数据源连接、复杂转换、跨库 JOIN。语法示例：</li></ul><div class="language-flux vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">flux</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>from(bucket: &quot;metrics&quot;)</span></span>
<span class="line"><span>  |&gt; range(start: -1h)</span></span>
<span class="line"><span>  |&gt; filter(fn: (r) =&gt; r._measurement == &quot;cpu&quot;)</span></span>
<span class="line"><span>  |&gt; aggregateWindow(every: 5m, fn: mean)</span></span></code></pre></div><ul><li><strong>内置任务与告警</strong>：用 Flux 脚本定义定时任务（Task）和告警规则（Alert），替代外部 Kapacitor。</li><li><strong>Token 认证体系</strong>：引入基于 API Token 的权限管理，支持 Org 级别的多租户隔离。</li><li><strong>统一 UI</strong>：Data Explorer、Notebook、Dashboard 全部集成在单一 Web 界面中。</li></ul><p>2.x 的争议点在于 <strong>Flux 的学习曲线</strong>——虽然功能强大，但函数式管道语法对习惯了 SQL 的用户并不友好。这也是 3.x 回归 SQL 的重要背景。</p><h3 id="influxdb-3-x-2023–至今-iox-引擎与云原生架构" tabindex="-1">InfluxDB 3.x（2023–至今）：IOx 引擎与云原生架构 <a class="header-anchor" href="#influxdb-3-x-2023–至今-iox-引擎与云原生架构" aria-label="Permalink to &quot;InfluxDB 3.x（2023–至今）：IOx 引擎与云原生架构&quot;">​</a></h3><p>3.x 代号为 <strong>IOx</strong>，是 InfluxDB 的&quot;涅槃重生&quot;。2021 年 InfluxData 宣布重写存储引擎，采用 <strong>Apache Arrow + Apache Parquet + DataFusion</strong> 的技术栈：</p><table tabindex="0"><thead><tr><th>维度</th><th>1.x/2.x（TSM）</th><th>3.x（IOx）</th></tr></thead><tbody><tr><td><strong>存储格式</strong></td><td>自研 TSM 文件</td><td>Apache Parquet（列存）</td></tr><tr><td><strong>内存模型</strong></td><td>自研 Cache</td><td>Apache Arrow（列式内存）</td></tr><tr><td><strong>查询引擎</strong></td><td>自研 InfluxQL/Flux</td><td>Apache DataFusion（基于 Arrow）</td></tr><tr><td><strong>查询语言</strong></td><td>InfluxQL / Flux</td><td>标准 SQL + InfluxQL 兼容</td></tr><tr><td><strong>对象存储</strong></td><td>本地磁盘 / EBS</td><td>S3、MinIO 等对象存储原生支持</td></tr><tr><td><strong>压缩比</strong></td><td>~10:1</td><td>~45:1（官方数据）</td></tr><tr><td><strong>查询性能</strong></td><td>中等</td><td>2.5x–45x 提升（视查询类型）</td></tr><tr><td><strong>架构模式</strong></td><td>单体 / 企业集群</td><td>存算分离、无状态查询节点</td></tr></tbody></table><p><strong>IOx 的核心优势</strong>：</p><ul><li><strong>云原生</strong>：数据持久化到对象存储，查询节点无状态，可独立扩缩容。</li><li><strong>生态兼容</strong>：Parquet 格式可以被 Spark、DuckDB、Pandas 等工具直接读取，打破数据孤岛。</li><li><strong>SQL 回归</strong>：支持标准 SQL 查询，大幅降低迁移和学习成本。</li><li><strong>无限水平扩展</strong>：通过增加查询节点即可提升并发查询能力，存储层由对象存储的弹性保障。</li></ul><blockquote><p>当前状态（截至 2025 年）：InfluxDB 3.x 核心引擎已开源（influxdb_iox 仓库），但完整的 InfluxDB 3.0 发行版仍在积极开发中。2.x 是当前生产环境的主流稳定版本，1.x 已进入维护模式。</p></blockquote><hr><h2 id="核心特性概览" tabindex="-1">核心特性概览 <a class="header-anchor" href="#核心特性概览" aria-label="Permalink to &quot;核心特性概览&quot;">​</a></h2><h3 id="_1-高写入吞吐" tabindex="-1">1. 高写入吞吐 <a class="header-anchor" href="#_1-高写入吞吐" aria-label="Permalink to &quot;1. 高写入吞吐&quot;">​</a></h3><p>InfluxDB 针对顺序追加写入进行了深度优化。单节点场景下，2.x 版本可达 <strong>数十万 points/秒</strong> 的写入性能。优化手段包括：</p><ul><li><strong>批量写入</strong>：Line Protocol 支持一次请求携带数千个数据点。</li><li><strong>WAL 顺序写</strong>：磁盘顺序 I/O 的性能远高于随机 I/O。</li><li><strong>内存缓冲</strong>：热数据先在内存中组织为 Cache，异步刷盘。</li><li><strong>时间分片（Shard）</strong>：数据按时间窗口分片存储，避免全局锁竞争。</li></ul><h3 id="_2-高效时间范围查询" tabindex="-1">2. 高效时间范围查询 <a class="header-anchor" href="#_2-高效时间范围查询" aria-label="Permalink to &quot;2. 高效时间范围查询&quot;">​</a></h3><p>时序数据库的查询 90% 以上都包含时间范围过滤。InfluxDB 通过以下机制保证查询效率：</p><ul><li><strong>时间分片裁剪</strong>：查询 <code>WHERE time &gt; now() - 1h</code> 时，只需扫描最近几个 shard，而非全表。</li><li><strong>Tag 索引</strong>：标签键值对被索引，支持快速等值过滤和分组。</li><li><strong>列式存储（3.x）</strong>：Parquet 格式下，只读取查询涉及的列，大幅减少 I/O。</li><li><strong>预聚合（Continuous Query / Task）</strong>：1.x 的 Continuous Query 和 2.x 的 Task 可以在数据写入时或定时执行聚合，将高频原始数据降采样为低频汇总数据。</li></ul><h3 id="_3-数据保留策略-retention-policy" tabindex="-1">3. 数据保留策略（Retention Policy） <a class="header-anchor" href="#_3-数据保留策略-retention-policy" aria-label="Permalink to &quot;3. 数据保留策略（Retention Policy）&quot;">​</a></h3><p><strong>Retention Policy（RP）</strong> 是 InfluxDB 的自动数据生命周期管理机制。你可以定义：</p><ul><li>数据保留时长（如 7 天、30 天、1 年）</li><li>数据分片精度（如每个 shard 覆盖 1 天或 7 天）</li><li>是否启用自动复制（仅企业版）</li></ul><p>到达保留期限的数据会被自动删除，无需人工干预。在 2.x 中，这一概念被整合进 <strong>Bucket 的 Retention Rule</strong>。</p><h3 id="_4-连续查询与任务-continuous-query-task" tabindex="-1">4. 连续查询与任务（Continuous Query / Task） <a class="header-anchor" href="#_4-连续查询与任务-continuous-query-task" aria-label="Permalink to &quot;4. 连续查询与任务（Continuous Query / Task）&quot;">​</a></h3><p>对于高频采集的原始数据，直接查询全量数据既慢又浪费资源。InfluxDB 提供了定时聚合机制：</p><ul><li><strong>1.x Continuous Query</strong>：在数据写入时自动触发预定义聚合，将 10 秒精度的原始数据实时汇总为 5 分钟精度。</li><li><strong>2.x Task</strong>：用 Flux 脚本定义定时任务，功能更灵活，支持告警、数据转换、跨库操作。</li></ul><p>示例：将 <code>cpu</code> measurement 的 10 秒数据降采样为 1 小时平均值：</p><div class="language-flux vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">flux</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>option task = {</span></span>
<span class="line"><span>  name: &quot;cpu_1h_downsample&quot;,</span></span>
<span class="line"><span>  every: 1h,</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>from(bucket: &quot;metrics&quot;)</span></span>
<span class="line"><span>  |&gt; range(start: -task.every)</span></span>
<span class="line"><span>  |&gt; filter(fn: (r) =&gt; r._measurement == &quot;cpu&quot;)</span></span>
<span class="line"><span>  |&gt; aggregateWindow(every: 1h, fn: mean)</span></span>
<span class="line"><span>  |&gt; to(bucket: &quot;metrics_1h&quot;)</span></span></code></pre></div><hr><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p>InfluxDB 在以下领域已被广泛验证：</p><table tabindex="0"><thead><tr><th>场景</th><th>典型数据</th><th>规模示例</th><th>核心价值</th></tr></thead><tbody><tr><td><strong>DevOps 监控</strong></td><td>CPU、内存、磁盘、网络、请求延迟</td><td>5 万台服务器 × 50 指标/10s</td><td>实时告警、历史趋势分析</td></tr><tr><td><strong>IoT 传感器数据</strong></td><td>温度、湿度、压力、GPS 坐标</td><td>100 万设备 × 10 指标/分钟</td><td>海量设备接入、边缘到云端聚合</td></tr><tr><td><strong>金融实时指标</strong></td><td>股票 Tick、风控指标、交易延迟</td><td>10 万笔/秒</td><td>毫秒级查询、合规审计</td></tr><tr><td><strong>应用性能监控（APM）</strong></td><td>调用链延迟、错误率、吞吐量</td><td>微服务 1000+ 节点</td><td>全链路追踪、异常定位</td></tr><tr><td><strong>能源管理</strong></td><td>光伏逆变器发电功率、电网负荷</td><td>10 万监测点/5 秒</td><td>预测性维护、能耗优化</td></tr><tr><td><strong>智慧城市</strong></td><td>环境监测、交通流量、灯杆数据</td><td>30 万设备/5 秒</td><td>城市级实时仪表盘</td></tr></tbody></table><h3 id="不适合的场景" tabindex="-1">不适合的场景 <a class="header-anchor" href="#不适合的场景" aria-label="Permalink to &quot;不适合的场景&quot;">​</a></h3><p>InfluxDB 并非万能。以下场景可能需要其他方案：</p><ul><li><strong>复杂事务处理</strong>：需要 ACID 事务、多行原子更新的场景，应使用关系型数据库。</li><li><strong>全文检索</strong>：日志文本搜索应使用 Elasticsearch 或 Loki。</li><li><strong>图关系分析</strong>：社交网络、知识图谱应使用 Neo4j 等图数据库。</li><li><strong>超高基数时间线</strong>（数千万级唯一标签组合）：TSM 引擎的索引内存消耗会变得不可控，3.x 的 IOx 引擎对此有改善但仍需谨慎评估。</li></ul><hr><h2 id="竞品对比-influxdb-vs-prometheus-vs-timescaledb-vs-opentsdb" tabindex="-1">竞品对比：InfluxDB vs Prometheus vs TimescaleDB vs OpenTSDB <a class="header-anchor" href="#竞品对比-influxdb-vs-prometheus-vs-timescaledb-vs-opentsdb" aria-label="Permalink to &quot;竞品对比：InfluxDB vs Prometheus vs TimescaleDB vs OpenTSDB&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>InfluxDB</th><th>Prometheus</th><th>TimescaleDB</th><th>OpenTSDB</th></tr></thead><tbody><tr><td><strong>数据模型</strong></td><td>Measurement + Tag + Field + Timestamp</td><td>Metric + Label（键值对）</td><td>标准关系表 + Hypertable</td><td>Metric + Tag + Timestamp</td></tr><tr><td><strong>查询语言</strong></td><td>InfluxQL / Flux / SQL（3.x）</td><td>PromQL</td><td>标准 SQL + 时序扩展</td><td>HTTP DSL / Java API</td></tr><tr><td><strong>存储引擎</strong></td><td>TSM（1.x/2.x）/ Parquet（3.x）</td><td>自研 TSDB（LevelDB 索引 + 自定义存储）</td><td>PostgreSQL + Hypertable 扩展</td><td>HBase（依赖 Hadoop 生态）</td></tr><tr><td><strong>架构模式</strong></td><td>单节点（开源）/ 集群（企业/3.x）</td><td>单体、多节点联邦</td><td>PostgreSQL 主从 / 分区</td><td>HBase RegionServer 集群</td></tr><tr><td><strong>部署复杂度</strong></td><td>低（单二进制）</td><td>低（单二进制）</td><td>中（需 PostgreSQL 基础）</td><td>高（HBase + ZooKeeper + HDFS）</td></tr><tr><td><strong>写入方式</strong></td><td>Push（主动推送）</td><td>Pull（主动拉取）+ Push Gateway</td><td>Push（标准 SQL INSERT）</td><td>Push（HTTP API）</td></tr><tr><td><strong>生态集成</strong></td><td>Telegraf / Grafana / Kafka / Pulsar</td><td>Grafana / AlertManager / Thanos / Cortex</td><td>Grafana / PostgreSQL 全生态</td><td>Grafana / OpenTelemetry</td></tr><tr><td><strong>数据类型</strong></td><td>Float / Int / String / Bool / Unsigned</td><td>Float64（主）+ 少量扩展</td><td>全部 PostgreSQL 类型</td><td>Float / Int / String</td></tr><tr><td><strong>水平扩展</strong></td><td>3.x 云原生支持</td><td>联邦 + Remote Write + Thanos/Cortex</td><td>分区表 + 读写分离</td><td>HBase 原生支持</td></tr><tr><td><strong>典型场景</strong></td><td>通用时序平台、IoT、APM</td><td>K8s 监控、服务指标</td><td>混合负载（时序+关系）</td><td>超大规模指标（PB 级）</td></tr></tbody></table><h3 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to &quot;选型建议&quot;">​</a></h3><ul><li><strong>选择 InfluxDB</strong>：如果你需要一个功能全面、生态丰富、对 SQL 有回归趋势的通用时序平台，且希望单节点即可起步。</li><li><strong>选择 Prometheus</strong>：如果你专注于 Kubernetes 和服务指标监控，且偏好 pull 模式的采集架构。</li><li><strong>选择 TimescaleDB</strong>：如果你已有 PostgreSQL 基础设施，或需要在同一数据库中混合处理时序数据和关系型业务数据。</li><li><strong>选择 OpenTSDB</strong>：如果你已有 Hadoop 生态，且需要存储 PB 级历史指标数据（新项目不建议）。</li></ul><hr><h2 id="完整数据链路架构" tabindex="-1">完整数据链路架构 <a class="header-anchor" href="#完整数据链路架构" aria-label="Permalink to &quot;完整数据链路架构&quot;">​</a></h2><p>下图展示了从数据采集到可视化的完整链路，InfluxDB 处于存储和查询的核心位置：</p>`,73)),(r(),l(g,null,{default:a(()=>[u(o,{id:"mermaid-983",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20%E9%87%87%E9%9B%86%E5%B1%82%5B%22%F0%9F%94%8C%20%E6%95%B0%E6%8D%AE%E9%87%87%E9%9B%86%E5%B1%82%22%5D%0A%20%20%20%20%20%20%20%20A1%5BTelegraf%5D%0A%20%20%20%20%20%20%20%20A2%5BPrometheus%20Exporter%5D%0A%20%20%20%20%20%20%20%20A3%5B%E8%87%AA%E5%AE%9A%E4%B9%89%E5%BA%94%E7%94%A8%5D%0A%20%20%20%20%20%20%20%20A4%5BIoT%20%E7%BD%91%E5%85%B3%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%E4%BC%A0%E8%BE%93%E5%B1%82%5B%22%F0%9F%93%A1%20%E6%95%B0%E6%8D%AE%E4%BC%A0%E8%BE%93%E5%B1%82%22%5D%0A%20%20%20%20%20%20%20%20B1%5BHTTP%20API%5D%0A%20%20%20%20%20%20%20%20B2%5BMQTT%20%2F%20Kafka%5D%0A%20%20%20%20%20%20%20%20B3%5BLine%20Protocol%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%E5%AD%98%E5%82%A8%E5%B1%82%5B%22%F0%9F%92%BE%20%E6%95%B0%E6%8D%AE%E5%AD%98%E5%82%A8%E5%B1%82%22%5D%0A%20%20%20%20%20%20%20%20C1%5B%22InfluxDB%3Cbr%2F%3ETSM%20%2F%20IOx%22%5D%0A%20%20%20%20%20%20%20%20C2%5B(WAL)%5D%0A%20%20%20%20%20%20%20%20C3%5B(Cache)%5D%0A%20%20%20%20%20%20%20%20C4%5B(TSM%20%2F%20Parquet)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%E5%A4%84%E7%90%86%E5%B1%82%5B%22%E2%9A%99%EF%B8%8F%20%E6%95%B0%E6%8D%AE%E5%A4%84%E7%90%86%E5%B1%82%22%5D%0A%20%20%20%20%20%20%20%20D1%5B%22Task%20%2F%20CQ%3Cbr%2F%3E%E9%99%8D%E9%87%87%E6%A0%B7%22%5D%0A%20%20%20%20%20%20%20%20D2%5B%22Retention%20Policy%3Cbr%2F%3E%E8%87%AA%E5%8A%A8%E8%BF%87%E6%9C%9F%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%E6%9F%A5%E8%AF%A2%E5%B1%82%5B%22%F0%9F%94%8D%20%E6%95%B0%E6%8D%AE%E6%9F%A5%E8%AF%A2%E5%B1%82%22%5D%0A%20%20%20%20%20%20%20%20E1%5B%22Flux%20%2F%20InfluxQL%20%2F%20SQL%22%5D%0A%20%20%20%20%20%20%20%20E2%5BHTTP%20API%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%E5%8F%AF%E8%A7%86%E5%8C%96%E5%B1%82%5B%22%F0%9F%93%8A%20%E5%8F%AF%E8%A7%86%E5%8C%96%E5%B1%82%22%5D%0A%20%20%20%20%20%20%20%20F1%5BGrafana%5D%0A%20%20%20%20%20%20%20%20F2%5BChronograf%5D%0A%20%20%20%20%20%20%20%20F3%5BData%20Explorer%5D%0A%20%20%20%20end%0A%0A%20%20%20%20A1%20--%3E%20B1%0A%20%20%20%20A2%20--%3E%20B1%0A%20%20%20%20A3%20--%3E%20B3%0A%20%20%20%20A4%20--%3E%20B2%0A%20%20%20%20B1%20--%3E%20C1%0A%20%20%20%20B2%20--%3E%20C1%0A%20%20%20%20B3%20--%3E%20C1%0A%20%20%20%20C1%20--%3E%20C2%0A%20%20%20%20C1%20--%3E%20C3%0A%20%20%20%20C1%20--%3E%20C4%0A%20%20%20%20C1%20--%3E%20D1%0A%20%20%20%20C1%20--%3E%20D2%0A%20%20%20%20C1%20--%3E%20E1%0A%20%20%20%20E1%20--%3E%20E2%0A%20%20%20%20E2%20--%3E%20F1%0A%20%20%20%20E2%20--%3E%20F2%0A%20%20%20%20E2%20--%3E%20F3%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=n('<hr><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>InfluxDB 从 2013 年诞生至今，经历了 TSM 引擎奠基（1.x）、Flux 平台化尝试（2.x）到 IOx 云原生重构（3.x）的三次蜕变。它以<strong>高写入吞吐</strong>、<strong>高效时间查询</strong>、<strong>自动数据生命周期管理</strong>为核心竞争力，在 DevOps 监控、IoT、金融和 APM 等场景中被广泛采用。</p><p>对于新项目，<strong>2.x 是当前最稳妥的选择</strong>——文档成熟、生态完善、社区活跃。如果你追求云原生架构和 SQL 兼容性，可以密切关注 3.x 的发展。无论选择哪个版本，理解 InfluxDB 的数据模型（Measurement、Tag、Field、Timestamp）和存储原理（时间分片、列存、压缩），都是用好它的前提。</p><hr><p><strong>延伸阅读预告</strong>：</p><ul><li><a href="./">InfluxDB 核心概念与数据模型</a> — 深入理解 Bucket、Measurement、Tag、Field、Series、Shard 等核心抽象</li><li><a href="./">InfluxDB 安装与快速上手</a> — 10 分钟在本地跑起来，完成第一条数据的写入和查询</li></ul>',7))])}const E=s(h,[["render",x]]);export{D as __pageData,E as default};
